package org.apache.commons.math3.optimization.linear;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MaxCountExceededException;
import org.apache.commons.math3.optimization.PointValuePair;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for SimplexSolver.solvePhase1.
 * Since solvePhase1 is protected, we use a Test subclass to expose it.
 */
public class SimplexSolver_solvePhase1_TriageGen0Test {

    private TestableSimplexSolver solver;
    private SimplexTableau mockTableau;
    private static final double EPSILON = 1e-9;

    // Subclass to access protected method
    private static class TestableSimplexSolver extends SimplexSolver {
        public TestableSimplexSolver() {
            super();
        }

        @Override
        public void solvePhase1(SimplexTableau tableau) throws MaxCountExceededException, UnboundedSolutionException, NoFeasibleSolutionException {
            super.solvePhase1(tableau);
        }

        // Override doIteration to control behavior in tests
        @Override
        protected void doIteration(SimplexTableau tableau) throws MaxCountExceededException, UnboundedSolutionException {
            super.doIteration(tableau);
        }
    }

    // Spy subclass to allow mocking of the protected doIteration method
    private static class SpySimplexSolver extends TestableSimplexSolver {
        public SpySimplexSolver() {
            super();
        }

        @Override
        protected void doIteration(SimplexTableau tableau) throws MaxCountExceededException, UnboundedSolutionException {
            // This will be mocked by Mockito
        }
    }

    @Before
    public void setUp() {
        solver = spy(new SpySimplexSolver());
        mockTableau = mock(SimplexTableau.class);
    }

    @Test
    public void testSolvePhase1_NoArtificialVariables_ReturnsImmediately() throws Exception {
        when(mockTableau.getNumArtificialVariables()).thenReturn(0);

        solver.solvePhase1(mockTableau);

        // Verify doIteration was never called because it returned early
        verify(solver, never()).doIteration(any(SimplexTableau.class));
    }

    @Test
    public void testSolvePhase1_OptimalImmediately_NoFeasibleExceptionThrown() throws Exception {
        // Case: Artificial variables exist, but it's already optimal, 
        // and W (entry at 0, rhsOffset) is NOT zero -> No Feasible Solution
        when(mockTableau.getNumArtificialVariables()).thenReturn(1);
        when(mockTableau.isOptimal()).thenReturn(true);
        when(mockTableau.getRhsOffset()).thenReturn(5);
        when(mockTableau.getEntry(0, 5)).thenReturn(1.0); // W != 0

        try {
            solver.solvePhase1(mockTableau);
            org.junit.Assert.fail("Expected NoFeasibleSolutionException to be thrown");
        } catch (NoFeasibleSolutionException e) {
            // Success
        }
    }

    @Test
    public void testSolvePhase1_OptimalImmediately_Success() throws Exception {
        // Case: Artificial variables exist, it's already optimal, 
        // and W (entry at 0, rhsOffset) IS zero -> Success
        when(mockTableau.getNumArtificialVariables()).thenReturn(1);
        when(mockTableau.isOptimal()).thenReturn(true);
        when(mockTableau.getRhsOffset()).thenReturn(5);
        when(mockTableau.getEntry(0, 5)).thenReturn(0.0); // W == 0

        solver.solvePhase1(mockTableau);

        verify(solver, never()).doIteration(any(SimplexTableau.class));
    }

    @Test
    public void testSolvePhase1_SuccessfulIterations() throws Exception {
        // Case: Performs iterations, becomes optimal, W is zero
        when(mockTableau.getNumArtificialVariables()).thenReturn(1);
        when(mockTableau.isOptimal()).thenReturn(false, true); // First call false, second true
        when(mockTableau.getRhsOffset()).thenReturn(5);
        when(mockTableau.getEntry(0, 5)).thenReturn(0.0);

        doNothing().when(solver).doIteration(mockTableau);

        solver.solvePhase1(mockTableau);

        verify(solver, times(1)).doIteration(mockTableau);
    }

    @Test
    public void testSolvePhase1_MaxCountExceededException() throws Exception {
        when(mockTableau.getNumArtificialVariables()).thenReturn(1);
        when(mockTableau.isOptimal()).thenReturn(false);
        doThrow(new MaxCountExceededException()).when(solver).doIteration(mockTableau);

        try {
            solver.solvePhase1(mockTableau);
            org.junit.Assert.fail("Expected MaxCountExceededException");
        } catch (MaxCountExceededException e) {
            // Success
        }
    }

    @Test
    public void testSolvePhase1_UnboundedSolutionException() throws Exception {
        when(mockTableau.getNumArtificialVariables()).thenReturn(1);
        when(mockTableau.isOptimal()).thenReturn(false);
        doThrow(new UnboundedSolutionException()).when(solver).doIteration(mockTableau);

        try {
            solver.solvePhase1(mockTableau);
            org.junit.Assert.fail("Expected UnboundedSolutionException");
        } catch (UnboundedSolutionException e) {
            // Success
        }
    }
}
